output.arguments:
{"command":"set +e
TD=$(mktemp -d); mkdir -p "$TD/home2" "$TD/home4" "$TD/xdg"
echo ==== empty CHEAT_CONFIG_PATH ====
env -u XDG_CONFIG_HOME HOME="$TD/home2" CHEAT_CONFIG_PATH= ./executable --init > "$TD/out" 2>"$TD/err"; echo rc=$?; grep -E '^    path:|git clone' "$TD/out"; cat "$TD/err"
echo ==== XDG ====
env -u CHEAT_CONFIG_PATH XDG_CONFIG_HOME="$TD/xdg" HOME="$TD/home4" ./executable --init > "$TD/out" 2>"$TD/err"; echo rc=$?; grep -E '^    path:|git clone' "$TD/out"; cat "$TD/err"
rm -rf "$TD""}

{"command":"set +e
TD=$(mktemp -d); mkdir -p "$TD/home" "$TD/xdg"
for label in default empty custom xdg; do
 echo ==== $label ====
 case $label in
 default) env -u CHEAT_CONFIG_PATH -u XDG_CONFIG_HOME HOME="$TD/home" python3 src/cheat.py --init > "$TD/out";;
 empty) env -u XDG_CONFIG_HOME HOME="$TD/home" CHEAT_CONFIG_PATH= python3 src/cheat.py --init > "$TD/out";;
 custom) env CHEAT_CONFIG_PATH="$TD/custom/conf.yml" HOME="$TD/home" python3 src/cheat.py --init > "$TD/out";;
 xdg) env -u CHEAT_CONFIG_PATH XDG_CONFIG_HOME="$TD/xdg" HOME="$TD/home" python3 src/cheat.py --init > "$TD/out";;
 esac
 grep -E '^    path:|git clone' "$TD/out"
done
rm -rf "$TD""}

